        }
        if lhs.tcpPort != rhs.tcpPort {
            return false
        }
        if lhs.device != rhs.device {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(nodeId)
        hasher.combine(name)
        hasher.combine(ip)
        hasher.combine(udpPort)
        hasher.combine(tcpPort)
        hasher.combine(device)
    }
}


